from pathlib import Path
import json,html,hashlib,datetime
HERE=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def esc(x):return html.escape(str(x),quote=True)
def sec(x):return 'převzato' if x is None else f'{x:.2f} s'
CSS='''body{margin:0;background:#f5f2e9;color:#28251e;font:17px/1.55 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:28px}h1{line-height:1.2}a{color:#275e81}table{border-collapse:collapse;width:100%;background:white}td,th{border:1px solid #d2cdc1;padding:10px;text-align:left;vertical-align:top}th{background:#e7e1d5}.line{background:white;border:1px solid #d2cdc1;padding:20px;margin:18px 0}.line img{display:block;max-width:100%;height:auto;margin:15px 0}.texts{display:grid;grid-template-columns:1fr 1fr;gap:20px}pre{font:19px/1.6 Georgia,serif;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.flag{color:#8a3d1d}.note{max-width:1000px}.overview{max-width:150px;max-height:180px}.toolbar{position:sticky;top:0;background:#e7e1d5;padding:10px;z-index:2}input{font:inherit;padding:6px}button{font:inherit}details{margin:12px 0}@media(max-width:700px){.texts{grid-template-columns:1fr}main{padding:14px}table{font-size:13px}}'''
def doc(title,body):return '<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>'+CSS+'</style><main>'+body+'</main></html>'
review_by_id={x['id']:x for x in read(HERE/'visual-review.json').get('line_samples',[])};manifest=read(HERE/'manifest.json');manifest['pages']=[p for p in manifest['pages'] if (HERE/'pages'/p['folio']/'medusa-run.json').exists() and read(HERE/'pages'/p['folio']/'medusa-run.json').get('status')=='success'];summary={'document_id':'VKO_M_II_220','scope':'100 new pages, fourth 100-page HTR batch','status':'raw_unreviewed','expert_reference':False,'cer':None,'wer':None,'paid_api_calls':0,'pages':[]};cards=[]
for p in manifest['pages']:
 folio=p['folio'];out=HERE/'pages'/folio
 cat=read(out/'catmus.candidates.json');med=read(out/'medusa.candidates.json');cr=read(out/'catmus-run.json');mr=read(out/'medusa-run.json')
 assert cr['status'] in ('success','reused') and mr['status'] in ('success','reused')
 assert [x['id'] for x in cat['lines']]==[x['id'] for x in med['lines']]
 rows=[];parts=[]
 for c,m in zip(cat['lines'],med['lines']):
  assert c['image_sha256']==m['image_sha256'] and c['bbox']==m['bbox']
  flags=list(c['review_flags'])+review_by_id.get(c['id'],{}).get('observed_flags',[])
  if not c['raw'].strip():flags.append('catmus_empty')
  if not m['raw'].strip():flags.append('medusa_empty')
  if m.get('hit_token_limit'):flags.append('medusa_token_limit')
  row={**c,'raw':None,'candidates':{'catmus':c['raw'],'medusa':m['raw']},'review_flags':flags,'status':'raw_unreviewed','medusa_ended_with_eos':m.get('ended_with_eos'),'medusa_hit_token_limit':m.get('hit_token_limit')};row.pop('raw');row['visual_review_note_cs']=review_by_id.get(c['id'],{}).get('notes_cs');rows.append(row)
  parts.append('<section class="line" data-flag="'+('1' if flags else '0')+'" id="'+esc(c['id'])+'"><strong>'+esc(c['id'])+'</strong> · oblast '+str(c['region_index']+1)+' <span class="flag">'+esc(', '.join(flags))+'</span><a href="'+esc(c['image'])+'"><img loading="lazy" src="'+esc(c['image'])+'" alt="Výřez '+esc(c['id'])+'"></a><div class="texts"><div><b>CATMuS 1.6.0 — surový výstup</b><pre>'+esc(c['raw'])+'</pre></div><div><b>MEDUSA 0.2Line-4B — surový výstup</b><pre>'+esc(m['raw'])+'</pre></div></div>'+('<p class="note"><b>Omezené obrazové pozorování:</b> '+esc(row['visual_review_note_cs'])+'</p>' if row['visual_review_note_cs'] else '')+'</section>')
 save(out/'comparison.json',{'folio':folio,'status':'raw_unreviewed','expert_review':False,'source':p['original'],'source_sha256':p['original_sha256'],'lines':rows})
 (out/'medusa.raw.txt').write_text('\n'.join(m['raw'] for m in med['lines'])+'\n',encoding='utf-8')
 body='<a href="../../index.html">← Všech 100 stran</a><h1>Folio '+esc(folio)+'</h1><p class="note">'+esc(p['notes_cs'])+'</p><p>Výstupy modelů bez odborné korektury. Shoda dvou modelů nepotvrzuje správnost. Jednotkou je segment; fragmenty a iniciály mohou způsobit více segmentů na jeden fyzický řádek. Zobrazené PNG mají 12 px přesahu a mohou obsahovat části sousedních řádků. CATMuS řádek interně vytěžuje a narovnává v Kraken rpred; Medusa dostává toto obdélníkové PNG. Zdrojová geometrie je společná, předzpracování se liší.</p><p><a href="overview.jpg">Původní vzhled strany</a> · <a href="selection-regions.jpg">Vybrané oblasti</a> · <a href="'+('segmentation-preview.jpg' if (out/'segmentation-preview.jpg').exists() else 'overview.jpg')+'">Náhled segmentace</a> · <a href="catmus.raw.txt">CATMuS TXT</a> · <a href="medusa.raw.txt">MEDUSA TXT</a> · <a href="comparison.json">JSON</a> · <a href="catmus-run.json">CATMuS běh</a> · <a href="medusa-run.json">MEDUSA běh</a></p><p>Segmentů: '+str(len(rows))+'. Rozpoznávání CATMuS: '+sec(cr.get('recognition_seconds'))+'; MEDUSA: '+sec(mr.get('recognition_seconds'))+'.</p><div class="toolbar"><label>Hledat ID nebo text <input id="search" type="search"></label> <label><input id="flags" type="checkbox"> Jen označené problémy</label> <span id="count"></span></div>'+''.join(parts)+'''<script>const rows=[...document.querySelectorAll('.line')];function filter(){const q=document.getElementById('search').value.toLocaleLowerCase(),flag=document.getElementById('flags').checked;let n=0;for(const r of rows){const ok=(!flag||r.dataset.flag==='1')&&r.textContent.toLocaleLowerCase().includes(q);r.hidden=!ok;if(ok)n++}document.getElementById('count').textContent=n+' / '+rows.length}document.getElementById('search').addEventListener('input',filter);document.getElementById('flags').addEventListener('change',filter);filter()</script>'''
 (out/'comparison.html').write_text(doc('M II 220 · '+folio,body),encoding='utf-8')
 s={'folio':folio,'layout':p['layout'],'reused':bool(p.get('reuse')),'segments':len(rows),'catmus_nonempty':cr['nonempty'],'medusa_nonempty':mr['nonempty'],'flagged_segments':sum(bool(x['review_flags']) for x in rows),'medusa_truncated':mr['truncated_lines'],'catmus_recognition_seconds':cr.get('recognition_seconds'),'medusa_recognition_seconds':mr.get('recognition_seconds'),'segmentation_seconds':cr.get('segmentation_seconds'),'crop_seconds':cr.get('crop_seconds'),'catmus_total_seconds':cr.get('total_seconds'),'notes_cs':p['notes_cs'],'polygonizer_fallback_events':cr.get('polygonizer_fallback_events',[])};summary['pages'].append(s)
 cards.append('<tr><td><a href="pages/'+folio+'/comparison.html"><img class="overview" src="pages/'+folio+'/overview.jpg" alt="'+folio+'"><br><b>'+folio+'</b></a></td><td>'+esc(p['notes_cs'])+('</td><td>převzato' if p.get('reuse') else '</td><td>nový běh')+'</td><td>'+str(len(rows))+'</td><td>'+str(s['catmus_nonempty'])+' / '+str(s['medusa_nonempty'])+'</td><td>'+sec(s['catmus_recognition_seconds'])+'</td><td>'+sec(s['medusa_recognition_seconds'])+'</td><td>'+str(s['flagged_segments'])+'</td></tr>')
summary['total_segments']=sum(x['segments'] for x in summary['pages']);summary['new_segments']=sum(x['segments'] for x in summary['pages'] if not x['reused']);summary['new_catmus_recognition_seconds']=sum(x['catmus_recognition_seconds'] or 0 for x in summary['pages']);summary['new_medusa_recognition_seconds']=sum(x['medusa_recognition_seconds'] or 0 for x in summary['pages']);summary['new_segmentation_seconds']=sum(x['segmentation_seconds'] or 0 for x in summary['pages']);summary['new_crop_seconds']=sum(x['crop_seconds'] or 0 for x in summary['pages']);summary['generated_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();save(HERE/'summary.json',summary)
body='<h1>M II 220 · 100 dalších stran · HTR pilot</h1><p class="note">CATMuS medieval 1.6.0 a ENC-PSL/Medusa0.2Line-4B, místní běh bez placených API. Dávka obsahuje 100 vybraných stran; aktuální úplnost uvádějí souhrnná data a manifest. Výběr od 184r do 235r podle seznamu v selection.json; nevypovídá o měřené přesnosti celého rukopisu.</p><p><a href="../pilot-index.html">Všechny etapy · 430 stran</a> · <a href="assessment.md">Závěr a metodika</a> · <a href="usage-report.md">Spotřeba</a> · <a href="ocr-proarc/proarc-ocr-next-100-pages.zip">ZIP pro ProArc</a> · <a href="visual-review.json">Rozsah obrazové kontroly</a> · <a href="validation.json">Technická kontrola</a> · <a href="summary.json">Souhrnná data</a> · <a href="selection.json">Výběr vzorku</a> · <a href="manifest.json">Zdroje a kontrolní součty</a> · <a href="ocr-proarc/README.md">TXT a ALTO pro ProArc</a> · <a href="../pilot-next-ten-pages/index.html">Druhá etapa</a></p><p>Celkem '+str(summary['total_segments'])+' segmentů. Každý odkaz na stranu otevře stejné obrazové výřezy vedle obou surových přepisů. Počty segmentů mohou zahrnovat fragmenty, rubriky a části iniciál. Okrajové poznámky mimo vybrané oblasti nejsou zpracované. Surové HTR je zachováno samostatně. <a href="../interpretation-fourth-100-pages/index.html">Latinské rekonstrukce a české překlady všech 100 stran</a> tvoří oddělenou návrhovou vrstvu. Rozsah obrazové kontroly je zaznamenán samostatně.</p><table><thead><tr><th>Strana</th><th>Rozvržení a omezení</th><th>Původ</th><th>Segmenty</th><th>Neprázdné CAT / MED</th><th>CAT rozpoznávání</th><th>MED rozpoznávání</th><th>Označené segmenty*</th></tr></thead><tbody>'+''.join(cards)+'</tbody></table><p>* Automatické geometrické příznaky, prázdné výstupy, limit generování a případné oblasti s opravou polygonizace. Příznaky čtení sousedního řádku jsou uvedeny jen u individuálně zaznamenaných případů. Nejde o počet chybných čtení. Časy nezahrnují načtení modelů, segmentaci ani lidskou korekturu; úplné rozdělení je v závěru. Surové Unicode řetězce nebyly normalizované.</p>'
if len(summary['pages'])<100:body=body.replace('Všechny etapy · 430 stran',f"Všechny etapy · {330+len(summary['pages'])} dokončených stran")
if not (HERE/'ocr-proarc/proarc-ocr-next-100-pages.zip').exists():body=body.replace('<a href="ocr-proarc/proarc-ocr-next-100-pages.zip">ZIP pro ProArc</a>', 'ZIP pro ProArc se připravuje')
(HERE/'index.html').write_text(doc('M II 220 · stostránková dávka',body),encoding='utf-8');print(json.dumps({'published_pages':len(summary['pages']),'segments':summary['total_segments']}),flush=True)
